class VehicleListing {const VehicleListing({required this.publicId,required this.title,required this.listingType,required this.providerName,required this.providerVerified,required this.availableNow,required this.phone,this.categoryName,this.description,this.passengerCapacity,this.publicAreaName,this.distanceKm,this.whatsappNumber,this.thumbnailUrl,this.images=const[]});final String publicId,title,listingType,providerName,phone;final String? categoryName,description,publicAreaName,whatsappNumber,thumbnailUrl;final bool providerVerified,availableNow;final int? passengerCapacity;final double? distanceKm;final List<String> images;factory VehicleListing.fromJson(Map<String,dynamic> j)=>VehicleListing(publicId:j['publicId']??'',title:j['title']??'',listingType:j['listingType']??'',providerName:j['providerName']??'Independent provider',providerVerified:j['providerVerified']==true||j['providerVerified']==1,availableNow:j['availableNow']==true||j['availableNow']==1,phone:j['phone']??'',categoryName:j['categoryName'],description:j['description'],passengerCapacity:(j['passengerCapacity'] as num?)?.toInt(),publicAreaName:j['publicAreaName'],distanceKm:(j['distanceKm'] as num?)?.toDouble(),whatsappNumber:j['whatsappNumber'],thumbnailUrl:j['thumbnailUrl'],images:(j['images'] as List? ?? const[]).map((e)=>e['imageUrl'] as String).toList());String get distanceLabel=>distanceKm==null?'Distance unavailable':distanceKm!<1?'${(distanceKm!*1000).round()} m away':'${distanceKm!.toStringAsFixed(1)} km away';String get typeLabel=>listingType.split('_').map((x)=>x[0].toUpperCase()+x.substring(1)).join(' ');}
